/*
 * Panel de contenido de MSG-01.
 *
 * El shell ya aporta la superficie de scroll del panel; aquí viven los estilos
 * del bloque de acciones, la lista, la paginación y los estados de pantalla.
 * Todos los colores salen de los tokens del design-system.
 */

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.subtitle {
  max-width: 560px;
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* Indicador de cifrado: estado real del MVP (claves en memoria), no una acción. */
.e2eeBar {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  margin: 0 0 14px;
  padding: 6px 10px;
  border: 1px solid var(--bw-badge-success-border);
  border-radius: var(--bw-radius);
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 14px;
}

.searchWrap {
  position: relative;
  flex: 0 1 300px;
  max-width: 300px;
}

.searchWrap > i {
  position: absolute;
  top: 50%;
  left: 10px;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  color: var(--bw-deep-steel);
  font-family: inherit;
  font-size: 13px;
  outline: none;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: 1px solid var(--bw-calibration-blue);
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: not-allowed;
  opacity: 0.65;
}

.scopeNote {
  font-size: 12px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
}

.threadCount {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.errorBanner {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 0 0 14px;
  padding: 12px 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

.loadingBlock {
  margin: 24px 0;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageCtrl {
  color: var(--bw-input-placeholder);
}

.pageCtrl:disabled {
  cursor: default;
}

.pageActive {
  border-color: var(--bw-deep-steel);
  background: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageActive:hover:not(:disabled) {
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

