import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount } from '../../lib/threads';
import type { ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * Firmado público de MSG-01: el shell lo pasa desde App.tsx.
   *
   * MSG-02 no existía cuando se escribió esta pantalla y abrir un hilo no lleva
   * a ningún sitio: se recibe y se ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Texto legible del fallo de red, para F-128.
 *
 * Lo que lanza `fetchThreadPage` no siempre es un `Error`: PostgREST rechaza con
 * un objeto plano `{ code, message }`, y `String(e)` de un objeto plano produce
 * `[object Object]`. Se sacan `code` y/o `message` cuando existen y, en última
 * instancia, se cae a un texto con sentido en vez de un hueco silencioso.
 */
function errorDetail(error: unknown): string {
  if (error instanceof Error) {
    return error.message || 'Error desconocido.';
  }
  if (typeof error === 'object' && error !== null) {
    const maybe = error as { code?: unknown; message?: unknown };
    const code = typeof maybe.code === 'string' ? maybe.code : '';
    const message = typeof maybe.message === 'string' ? maybe.message : '';
    if (code && message) return `${code}: ${message}`;
    if (message) return message;
    if (code) return code;
  }
  return 'Error desconocido.';
}

/**
 * MSG-01 · Lista de Hilos.
 *
 * Pantalla: posee el estado de búsqueda y de página, pide cada página a
 * `fetchThreadPage` y delega el pintado de filas en `ThreadList`.
 */
export function Messages({ profile, now = new Date() }: MessagesProps) {
  const [inputValue, setInputValue] = useState('');
  const [term, setTerm] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: term, page })
      .then((result) => {
        if (cancelled) return;
        setThreads(result.threads);
        setTotal(result.total);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setThreads([]);
        setTotal(0);
        setError(err);
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, term, page]);

  const pages = pageCount(total);
  const threadWord = total === 1 ? 'hilo' : 'hilos';
  const resultInfo = `${total.toLocaleString('es-ES')} ${threadWord} · Página ${page.toLocaleString(
    'es-ES',
  )} de ${pages.toLocaleString('es-ES')}`;

  const applySearch = () => {
    setPage(1);
    setTerm(inputValue);
  };

  return (
    <>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        <span>E2EE activo · claves en memoria de sesión</span>
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => {
              if (e.key !== 'Enter') return;
              e.preventDefault();
              applySearch();
            }}
          />
        </div>

        <button type="button" className={styles.primaryBtn} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>

        <span className={styles.scopeNote} data-testid="directorio-scope">
          El Directorio (DIR-01) queda fuera del MVP.
        </span>

        {!error && !loading ? (
          <span className={styles.threadCount} data-testid="pag-info">
            {resultInfo}
          </span>
        ) : null}
      </div>

      {error ? (
        <div role="alert" className={styles.errorBanner}>
          <i className="ti ti-alert-triangle" aria-hidden="true" />
          <span>No se pudieron cargar los hilos. {errorDetail(error)}</span>
        </div>
      ) : loading ? (
        <p className={styles.loadingBlock}>Cargando hilos…</p>
      ) : (
        <ThreadList threads={threads} now={now} onOpen={() => {}} />
      )}

      {!error && !loading ? (
        <div className={styles.pagination}>
          <button
            type="button"
            className={`${styles.pageBtn} ${styles.pageCtrl}`}
            aria-label="Página anterior"
            disabled={page <= 1}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            ‹
          </button>

          {Array.from({ length: pages }, (_, i) => i + 1).map((n) => (
            <button
              key={n}
              type="button"
              aria-current={n === page ? 'page' : undefined}
              className={n === page ? `${styles.pageBtn} ${styles.pageActive}` : styles.pageBtn}
              onClick={() => setPage(n)}
            >
              {n}
            </button>
          ))}

          <button
            type="button"
            className={`${styles.pageBtn} ${styles.pageCtrl}`}
            aria-label="Página siguiente"
            disabled={page >= pages}
            onClick={() => setPage((p) => p + 1)}
          >
            ›
          </button>
        </div>
      ) : null}
    </>
  );
}

