/*
 * Lista de hilos de MSG-01.
 *
 * Los colores salen todos de los tokens del design-system. La superficie de
 * tarjeta que el mock pinta de blanco puro se resuelve con el token claro más
 * próximo de la paleta (`--bw-warm-cream`); no hay token de blanco puro.
 */

.threadList {
  margin: 0;
  padding: 0;
  list-style: none;
  overflow: hidden;
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

/* El botón ocupa toda la fila y es quien recibe el nombre accesible del hilo. */
.rowButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  gap: 4px 12px;
  align-items: center;
  width: 100%;
  margin: 0;
  padding: 14px 16px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.rowButton:hover {
  background: var(--bw-hover-surface);
}

.rowButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.rowHead {
  grid-column: 1;
  grid-row: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.rowTime {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.rowFoot {
  grid-column: 1 / -1;
  grid-row: 2;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  flex-shrink: 0;
  padding: 1px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  white-space: nowrap;
}

.preview {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  font-size: 12px;
  color: var(--bw-steel-mist);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  flex-shrink: 0;
  padding: 2px 7px;
  border: 1px solid transparent;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.toneNeutral {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.toneInfo {
  background: var(--bw-chip-active-bg);
  border-color: var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.toneWarn {
  background: var(--bw-badge-warning-bg);
  border-color: var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.toneSuccess {
  background: var(--bw-badge-success-bg);
  border-color: var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.toneClosed {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

/* Estado vacío: contenedor aparte, nunca un <li> dentro del <ul> de filas. */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 48px 24px;
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  text-align: center;
}

.emptyText {
  max-width: 480px;
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.emptyAction {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  padding: 0 18px;
  border: 1px solid var(--bw-calibration-blue);
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: not-allowed;
  opacity: 0.65;
}

.emptyNote {
  margin: 0;
  font-size: 12px;
  color: var(--bw-input-placeholder);
}

