import { previewLabel, relativeTime, stateTone } from '../../lib/threads';
import type { StateTone, ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Diccionario tono → clase de badge.
 *
 * Las cinco entradas viven en el CSS Module como `.toneNeutral`, `.toneInfo`,
 * etc. Se declara `Record<StateTone, string | undefined>` porque, con
 * `noUncheckedIndexedAccess`, cualquier propiedad de `styles` puede faltar en el
 * fichero `.module.css`; el `?? ''` al consumirla deja la fila sin adorno en vez
 * de escribir `undefined` en el atributo `class`.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.toneNeutral,
  info: styles.toneInfo,
  warn: styles.toneWarn,
  success: styles.toneSuccess,
  closed: styles.toneClosed,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (threadId: string) => void;
}

/**
 * Lista de hilos de MSG-01. Presentacional.
 *
 * No carga datos ni pagina: pinta las filas en el orden en que las recibe — el
 * orden descendente por `last_item_at` lo pone el servidor.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    // El estado vacío va en un contenedor aparte, fuera de cualquier <ul>:
    // con cero hilos no debe quedar ningún `listitem` en el documento.
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar
          con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyAction} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyNote}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          // La fila conserva su rol `listitem`: el elemento pulsable es el
          // botón que vive DENTRO del <li>, nunca un role encima del <li>.
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowButton}
              aria-label={thread.counterpartyName}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowHead}>
                <span className={styles.orgName}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                ) : null}
              </span>
              <time className={styles.rowTime} dateTime={thread.lastItemAt}>
                {relativeTime(thread.lastItemAt, now)}
              </time>
              <span className={styles.rowFoot}>
                <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.stateBadge} ${toneClass}`}>{thread.state}</span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
